/* add record */
async function fpOf(f){const d=new FormData(f),file=d.get('file'),dh=file&&file.size?await sha(await file.arrayBuffer()):'';return{d,file,dh,h:await sha(JSON.stringify({t:d.get('t'),op:d.get('op'),rid:d.get('rid'),amt:d.get('amt'),desc:d.get('desc'),doc:dh}))}}
function openAdd(){modal(`<h2>Add a record</h2><p class="muted">This acts like a staff member saving a record in an office database. CYFR captures the change on its own.</p>
 <form id="af" class="fgrid"><label>Office and table<select name="t">${TABLES.map(t=>`<option value="${t[0]}">${t[1]} · ${t[0]}</option>`).join('')}</select></label><label>Operation<select name="op"><option>INSERT</option><option>UPDATE</option><option>DELETE</option></select></label>
 <label>Record ID<input name="rid" type="number" value="${1000+Math.floor(Math.random()*9000)}" required></label><label>Amount (₱)<input name="amt" type="number" min="0" step="0.01" placeholder="0.00"></label>
 <label class="full">Description<input name="desc" placeholder="e.g. Payment to ABC Construction" required></label><label class="full">Supporting document (optional)<input name="file" type="file"></label>
 <div class="full fp"><small>Live fingerprint (SHA-256). Changes with every edit.</small><div class="mono" id="fp">Enter a description to see the fingerprint.</div></div>
 <div class="full row"><button type="button" class="btn" id="cx">Cancel</button><button class="btn primary">Save record</button></div></form>`);
 const f=$('#af'),upd=async()=>{if(f.desc.value)$('#fp').textContent=(await fpOf(f)).h};f.oninput=upd;f.onchange=upd;$('#cx').onclick=closeModal;
 f.onsubmit=async e=>{e.preventDefault();const r=await fpOf(f),t=TABLES.find(x=>x[0]==r.d.get('t')),op=r.d.get('op'),out=state.outage;
  const S=[['Change captured','Database trigger saw the '+op+' on '+t[0]],['Fingerprint created','SHA-256 saved to the local ledger'],[out?'Held in offline queue':'Added to the next batch',out?'No connection. It will send when the connection returns':'Queued for anchoring'],[out?'Waiting for connection':'Anchored to eGovChain',out?'Nothing is lost':'Fingerprint recorded on-chain']];
  const paint=i=>$('.modal').innerHTML=`<h2>Saving record</h2><div class="pl">${S.map((s,k)=>`<div class="${k<i?'d':k==i?'r':'p'}"><i>${k<i?'✓':k==i?'<span class="spin"></span>':''}</i><div><b>${s[0]}</b><small>${s[1]}</small></div></div>`).join('')}</div>`;
  paint(0);await sleep(700);paint(1);await sleep(800);
  const e1=addEntry({table:t[0],office:t[1],op,rid:+r.d.get('rid'),hash:r.h,desc:r.d.get('desc'),amt:r.d.get('amt'),docHash:r.dh||undefined,docName:r.dh?r.file.name:undefined});refresh();
  paint(2);await sleep(800);paint(3);await sleep(900);if(!out){e1.status='Anchored';e1.batch='B-'+(++state.batch);e1.tx='0x'+hash(e1.hash).slice(0,40)}
  $('.modal').innerHTML=`<h2>Record saved</h2><div class="alert ${out?'warn':'ok'}" style="margin:12px 0"><span><b>#${e1.seq}</b> ${out?'is in the offline queue and will anchor when the connection returns.':'was anchored in batch '+e1.batch+'.'}</span></div><small class="muted">Fingerprint</small><div class="mono" style="word-break:break-all;margin-bottom:12px">${r.h}</div>${r.dh?'<p class="muted">Document registered. Check it later under Verify records.</p>':''}<div class="row"><button class="btn" id="ao">Add another</button><button class="btn primary" id="vl">View in ledger</button></div>`;
  refresh();$('#ao').onclick=openAdd;$('#vl').onclick=()=>{closeModal();location.hash='#/ledger'}}}
/* connection wizard */
function openConn(){modal(`<h2>Add a connection</h2><p class="muted">Connect an existing database. CYFR only watches changes and never moves your data.</p><form id="cf" class="fgrid"><label class="full">Connection name<input name="n" required placeholder="e.g. Cashier collections"></label><label>Database engine<select name="e"><option>MySQL 8.0</option><option>MariaDB 10.6</option><option>MS Access (.accdb)</option></select></label><label>Office<select name="o">${OFFICES.map(o=>`<option>${o}</option>`).join('')}</select></label><label class="full">Host or file path<input name="h" required placeholder="10.10.4.40"></label><label>Read-only username<input name="u" value="cyfr_reader"></label><label>Password<input name="p" type="password" value="••••••••"></label><div class="full row"><button type="button" class="btn" id="cx">Cancel</button><button class="btn primary">Test connection</button></div></form>`);
 $('#cx').onclick=closeModal;$('#cf').onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));$('.modal').innerHTML=`<h2>Testing connection</h2><p class="muted"><span class="spin"></span> Reaching ${esc(v.h)}…</p>`;await sleep(1300);
  const T=['payments','disbursements','vouchers','permits','receipts','audit_log'];$('.modal').innerHTML=`<h2>Connection works</h2><p class="muted">Choose the tables CYFR should watch in ${esc(v.n)}.</p><div class="checks">${T.map((t,i)=>`<label><input type="checkbox" ${i<4?'checked':''} value="${t}"> ${t}</label>`).join('')}</div><div class="row"><button class="btn" id="cx">Cancel</button><button class="btn primary" id="sv">Save connection</button></div>`;$('#cx').onclick=closeModal;
  $('#sv').onclick=()=>{const n=document.querySelectorAll('.checks input:checked').length;conns.push({id:Date.now(),name:v.n,engine:v.e,host:v.h,office:v.o,tables:n,status:'Connected',sync:'Just now'});closeModal();toast(v.n+' is connected, watching '+n+' tables');render()}}}
