const ago=m=>new Date(Date.now()-m*6e4),ME=sessionStorage.getItem('cyfr_user')||'ito.admin@nagacity.gov.ph';
const notes=[{type:'bad',m:'Verification flagged 1 mismatch in payments#1204',t:ago(25),read:false},{type:'info',m:'i-Gov service requests is not connected yet',t:ago(90),read:false},{type:'ok',m:'Batch B-412 anchored (6 records)',t:ago(180),read:true}];
