function notify(type,m){if(type!='info'&&!state.prefs[type])return;notes.unshift({type,m,t:new Date(),read:false});bell()}
function bell(){const n=notes.filter(x=>!x.read).length,b=$('#bd');if(b){b.hidden=!n;b.textContent=n}const p=$('#np');if(!p||p.hidden)return;
 const C={bad:'var(--bad)',ok:'var(--ok)',warn:'var(--warn)',info:'var(--blue)'},R={bad:'#/verify',ok:'#/ledger',warn:'#/overview',info:'#/connections'};
 p.innerHTML=`<header><b>Notifications</b><button class="btn sm" id="mr">Mark all as read</button></header>${notes.length?notes.slice(0,8).map((x,i)=>`<button class="n ${x.read?'rd':'un'}" data-i="${i}"><span class="dot" style="background:${C[x.type]}"></span><span><b>${esc(x.m)}</b><small>${x.t.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</small></span></button>`).join(''):'<p class="muted" style="padding:14px">You are all caught up.</p>'}`;
 $('#mr').onclick=()=>{notes.forEach(x=>x.read=true);bell()};p.querySelectorAll('.n').forEach(b=>b.onclick=()=>{const x=notes[+b.dataset.i];x.read=true;location.hash=R[x.type];p.hidden=true;bell()})}
$('#bell').onclick=e=>{e.stopPropagation();$('#np').hidden=!$('#np').hidden;bell()};document.addEventListener('click',e=>{if(!e.target.closest('.bellw'))$('#np').hidden=true});
document.addEventListener('keydown',e=>{if(e.key=='n'&&!e.target.closest('input,select,textarea')&&!$('#modal'))openAdd()});
