/* printable sheet */
async function sheet(title,body,ref,csv){const html=`<div class="lh"><div style="display:flex;gap:10px;align-items:center"><span class="logo">C</span><div><b style="color:#0A2540">CYFR Blockchain Middleware</b><div class="muted">${esc(state.org.lgu)} · ${esc(state.org.office)}</div></div></div><div style="text-align:right"><b>${esc(title)}</b><div class="muted">Ref ${esc(ref||'')} · ${new Date().toLocaleDateString([], {year:'numeric',month:'long',day:'numeric'})}</div></div></div>${body}<div class="sig"><div>Prepared by: ${esc(ME)}</div><div>Noted by (Internal Audit / COA)</div></div><div class="ft">Report fingerprint (SHA-256 of this document): ${await sha(body+title)}<br>Generated by CYFR. Demo data for prototype purposes.</div>`;
 const m=modal(`<div class="sheet" id="sheet">${html}</div><div class="row no-print" style="margin-top:14px"><button class="btn" id="cx">Close</button><div style="display:flex;gap:8px">${csv?'<button class="btn" id="dc">Download CSV</button>':''}<button class="btn primary" id="pr">Print or save as PDF</button></div></div>`);m.style.width='min(860px,100%)';$('#cx').onclick=closeModal;$('#pr').onclick=()=>window.print();csv&&($('#dc').onclick=csv)}
function repBody(i,days){const tot=data90[OFFICES[0]].map((_,k)=>sum(OFFICES.map(o=>data90[o][k]))).slice(-days),lb=tot.map((_,k)=>new Date(Date.now()-(tot.length-1-k)*864e5).toLocaleDateString([], {month:'short',day:'numeric'})),tam=ledger.filter(l=>l.tampered);
 const stats=`<div class="stats"><div><b>${sum(tot).toLocaleString()}</b><small>Records fingerprinted</small></div><div><b>${(sum(tot)-queueN()).toLocaleString()}</b><small>Anchored</small></div><div><b>${queueN()}</b><small>In offline queue</small></div><div><b>${tam.length}</b><small>Mismatches</small></div></div>`;
 if(i==0)return stats+`<h3>Daily volume</h3>${lineChart(tot,'bar',lb)}<h3>Activity by office</h3><table><tbody>${OFFICES.map(o=>`<tr><td>${o}</td><td>${sum(data90[o].slice(-days)).toLocaleString()}</td></tr>`).join('')}</tbody></table><h3>Most recent entries</h3>${ledgerTable(ledger.slice(0,10))}`;
 if(i==1)return stats+`<h3>Findings</h3>${tam.length?`<table><thead><tr><th>Record</th><th>Batch</th><th>Anchored fingerprint</th><th>Current fingerprint</th></tr></thead><tbody>${tam.map(l=>`<tr><td>${l.table}#${l.rid}</td><td>${l.batch}</td><td class="mono">${short(l.hash)}</td><td class="mono">${short(l.live)}</td></tr>`).join('')}</tbody></table>`:`<p>No mismatches were found${state.lastVerify?' at the last verification ('+state.lastVerify+')':', but verification has not been run in this session'}.</p>`}<p class="muted">Detection applies from the moment a fingerprint is anchored.</p>`;
 return stats+`<h3>Compliance alignment</h3><table><thead><tr><th>Mandate</th><th>How CYFR supports it</th><th>Readiness</th></tr></thead><tbody><tr><td>RA 12254 E-Governance Act</td><td>Secure, interoperable record handling across offices</td><td>92%</td></tr><tr><td>CADENA Act (pending in the House)</td><td>Verifiable budget and disbursement records</td><td>78%</td></tr><tr><td>RA 10173 Data Privacy Act</td><td>Only fingerprints leave the office</td><td>100%</td></tr></tbody></table><p class="muted">This summary supports audit work. It is not a legal certification.</p>`}
const REP=[['Monthly integrity report','Fingerprint counts, anchoring and recent entries'],['Tamper findings','Records that did not match their anchored fingerprint'],['Compliance summary','Alignment with RA 12254, the proposed CADENA Act and RA 10173']];
pages.reports.r=()=>`<div class="grid g3">${REP.map((r,i)=>`<div class="card chain-card"><h2>${r[0]}</h2><div class="muted">${r[1]}</div><select id="p${i}"><option value="7">Last 7 days</option><option value="30" selected>Last 30 days</option><option value="90">Last 90 days</option></select><div class="row"><button class="btn" data-r="${i}">CSV</button><button class="btn primary" data-v="${i}">Preview report</button></div></div>`).join('')}</div>
<div class="card"><h2 style="margin-bottom:12px">Compliance readiness</h2><div class="list">${[['RA 12254 E-Governance Act','Secure, interoperable systems',92],['CADENA Act (pending in the House)','Verifiable budget and disbursement records',78],['RA 10173 Data Privacy Act','Only fingerprints leave the office',100]].map(c=>`<div><div class="row"><span><b>${c[0]}</b> <span class="muted">${c[1]}</span></span><b>${c[2]}%</b></div><div class="bar"><i style="width:${c[2]}%"></i></div></div>`).join('')}</div></div>`;
pages.reports.after=function(){const csv=i=>()=>download(`cyfr-${['monthly-integrity','tamper-findings','compliance-summary'][i]}.csv`,'seq,table,operation,status\n'+ledger.slice(0,25).map(l=>[l.seq,l.table,l.op,l.tampered?'Mismatch':l.status].join(',')).join('\n'));
 document.querySelectorAll('[data-r]').forEach(b=>b.onclick=csv(+b.dataset.r));document.querySelectorAll('[data-v]').forEach(b=>b.onclick=()=>{const i=+b.dataset.v,d=+$('#p'+i).value;sheet(REP[i][0],repBody(i,d),'R-'+(2610+i)+'-'+d,csv(i))})};
