pages.settings={t:'Settings',s:'Office profile, anchoring, alerts, security and users',r(){const t=state.tab,S=state.org;
 const tabs=`<div class="tabs" role="tablist">${[['general','General'],['users','Users and roles'],['security','Security'],['activity','Activity log']].map(x=>`<button data-tab="${x[0]}" class="${t==x[0]?'on':''}">${x[1]}</button>`).join('')}</div>`;
 if(t=='general')return tabs+`<div class="grid g2e"><div class="card"><h2>Office profile</h2><div class="list" style="margin-top:12px"><label>Local government<br><input id="s1" value="${esc(S.lgu)}" style="width:100%"></label><label>Office<br><input id="s2" value="${esc(S.office)}" style="width:100%"></label><label>Contact email<br><input id="s3" value="${esc(S.email)}" style="width:100%"></label><button class="btn primary" id="sv">Save changes</button></div></div>
 <div class="card"><h2>Anchoring</h2><div class="setrow"><span>Batch frequency<small>How often fingerprints are sent to the network</small></span><select id="bf"><option>Every 5 minutes</option><option>Hourly</option><option>Daily at 6:00 PM</option></select></div><div class="setrow"><span>Pause anchoring<small>Fingerprints keep queuing locally</small></span><label class="switch"><input type="checkbox" id="ps" ${state.paused?'checked':''}><span></span></label></div><h2 style="margin-top:16px">Alerts</h2>${[['bad','Mismatch alerts'],['ok','Batch confirmations'],['warn','Outage alerts']].map(x=>`<div class="setrow"><span>${x[1]}</span><label class="switch"><input type="checkbox" data-pf="${x[0]}" ${state.prefs[x[0]]?'checked':''}><span></span></label></div>`).join('')}</div></div>
 <div class="card"><div class="row"><span><b>Reset demo data</b><br><span class="muted">Reloads the prototype with its original sample data.</span></span><button class="btn danger" id="rs">Reset demo</button></div></div>`;
 if(t=='users')return tabs+`<div class="card"><div class="card-h"><h2>Users</h2><button class="btn primary" id="inv">Invite user</button></div><div class="scroll"><table><thead><tr><th>Name</th><th>Email</th><th>Office</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${users.map((u,i)=>`<tr><td><b>${esc(u.n)}</b></td><td>${esc(u.e)}</td><td>${u.o}</td><td><select data-ur="${i}">${Object.keys(ROLES).map(r=>`<option ${r==u.r?'selected':''}>${r}</option>`).join('')}</select></td><td>${pill(u.s,u.s=='Active'?'':u.s=='Invited'?'blue':'gray')}</td><td>${i?`<button class="btn sm" data-ut="${i}">${u.s=='Deactivated'?'Reactivate':'Deactivate'}</button>`:''}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Roles</h2><div class="list" style="margin-top:12px">${Object.entries(ROLES).map(([k,v])=>`<div class="row"><b>${k}</b><span class="muted">${v}</span></div>`).join('')}</div></div>`;
 if(t=='security')return tabs+`<div class="grid g2e"><div class="card"><h2>PKI certificate</h2><div class="setrow"><span>Status<small>Issued to ${esc(ME)}</small></span>${pill('Valid')}</div><div class="setrow"><span>Expires<small>Renew 30 days before expiry</small></span><b>Jun 30, 2027</b></div><div class="setrow"><span>Session timeout</span><select><option>15 minutes</option><option>30 minutes</option><option>1 hour</option></select></div></div><div class="card"><h2>Connector API key</h2><p class="muted">Used by the database triggers to send changes to CYFR. Rotating a key disconnects connectors until they are updated.</p><div class="mono" id="key" style="margin:12px 0">cyfr_live_••••••••••••••••••••</div><button class="btn" id="rk">Rotate key</button></div></div>`;
 return tabs+`<div class="card"><div class="card-h"><h2>Activity log</h2><button class="btn" id="al">Export CSV</button></div><div class="scroll"><table><thead><tr><th>Time</th><th>User</th><th>Action</th></tr></thead><tbody>${actlog.slice(0,25).map(a=>`<tr><td>${a.t.toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}</td><td>${esc(a.u)}</td><td>${esc(a.a)}</td></tr>`).join('')}</tbody></table></div></div>`},
 after(){const g=s=>document.querySelectorAll(s);g('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});
  const sv=$('#sv');if(sv){sv.onclick=()=>{state.org={lgu:$('#s1').value,office:$('#s2').value,email:$('#s3').value};$('#orgname').textContent=state.org.office.replace('Information Technology Office','Naga City ITO');toast('Settings saved')};$('#ps').onchange=e=>{state.paused=e.target.checked;toast(state.paused?'Anchoring paused. Records will queue':'Anchoring resumed');if(!state.paused)anchorQueued()};g('[data-pf]').forEach(c=>c.onchange=()=>{state.prefs[c.dataset.pf]=c.checked;toast('Alert preference saved')});$('#bf').onchange=()=>toast('Batch frequency saved');$('#rs').onclick=()=>location.reload()}
  g('[data-ur]').forEach(s=>s.onchange=()=>{users[+s.dataset.ur].r=s.value;toast('Role updated to '+s.value)});g('[data-ut]').forEach(b=>b.onclick=()=>{const u=users[+b.dataset.ut];u.s=u.s=='Deactivated'?'Active':'Deactivated';toast(u.n+' is now '+u.s.toLowerCase());render()});
  const inv=$('#inv');inv&&(inv.onclick=()=>{modal(`<h2>Invite a user</h2><form id="uf" class="fgrid"><label class="full">Full name<input name="n" required></label><label class="full">Email<input name="e" type="email" required></label><label>Role<select name="r">${Object.keys(ROLES).map(r=>`<option>${r}</option>`).join('')}</select></label><label>Office<select name="o">${OFFICES.map(o=>`<option>${o}</option>`).join('')}</select></label><div class="full row"><button type="button" class="btn" id="cx">Cancel</button><button class="btn primary">Send invitation</button></div></form>`);$('#cx').onclick=closeModal;$('#uf').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));users.push({n:v.n,e:v.e,r:v.r,o:v.o,s:'Invited'});closeModal();toast('Invitation sent to '+v.e);render()}});
  const rk=$('#rk');rk&&(rk.onclick=()=>{$('#key').textContent='cyfr_live_'+hash(''+Date.now()).slice(0,32);toast('New key created. Copy it now, it is shown once')});
  const al=$('#al');al&&(al.onclick=()=>download('cyfr-activity-log.csv','time,user,action\n'+actlog.map(a=>[a.t.toISOString(),a.u,'"'+a.a+'"'].join(',')).join('\n')))}};
bell();render();
/* ---------- UPGRADE 4: guided tamper, verification run, outage and restore simulations ---------- */
Object.assign(state,{outageType:'internet',outageSince:0});
const OUT={internet:['No connection to eGovChain.','Changes are fingerprinted locally and held in the offline queue.'],power:['Power failure.','Office servers restarted on backup power. CYFR recovered its local ledger and is queuing new changes.'],both:['Power and internet are down.','CYFR is running from its local ledger. Everything is queued and nothing is lost.']};
function verifyResult(){const t=ledger.filter(l=>l.tampered);if(!t.length)return `<div class="alert ok"><span><b>All ${ledger.length} records match.</b> Checked at ${state.lastVerify}.</span></div>`;
 return `<div class="alert bad"><span><b>${t.length} mismatch${t.length>1?'es':''} found.</b> Checked at ${state.lastVerify}.</span></div><div class="scroll" style="margin-top:12px"><table><thead><tr><th>Record</th><th>Change detected</th><th>Anchored fingerprint</th><th>Current fingerprint</th><th>Batch</th></tr></thead><tbody>${t.map(l=>`<tr class="flag"><td>${l.table}#${l.rid}</td><td>${l.tamperKind=='del'?'Record deleted':'Value edited'}</td><td class="mono">${short(l.hash)}</td><td class="mono">${short(l.live)}</td><td>${l.batch}</td></tr>`).join('')}</tbody></table></div>`}
/* tamper simulator */
function openTamper(){const cand=ledger.filter(l=>l.status=='Anchored'&&!l.tampered).slice(0,15);if(!cand.length){toast('No anchored records are available to change');return}
 modal(`<h2>Simulate tampering</h2><p class="muted">This acts as an administrator with valid credentials changing a record directly in the database, outside any normal workflow. CYFR does not block it. It proves the change later.</p><form id="tf" class="fgrid"><label class="full">Record<select name="s">${cand.map(l=>`<option value="${l.seq}">#${l.seq} · ${l.table}#${l.rid} · ${l.office}</option>`).join('')}</select></label>
 <div class="full" style="display:grid;gap:8px"><label class="opt"><input type="radio" name="k" value="edit" checked><span><b>Edit a value</b><small>Quietly change the amount on the record</small></span></label><label class="opt"><input type="radio" name="k" value="del"><span><b>Delete the record</b><small>Remove the row and leave a gap in the sequence</small></span></label></div>
 <label class="full" id="tv">New amount (₱)<input name="v" type="number" min="0"></label>
 <div class="full fp"><small>Anchored fingerprint (on-chain)</small><div class="mono" id="f0"></div><small>Fingerprint after your change</small><div class="mono new" id="f1"></div></div>
 <div class="full row"><button type="button" class="btn" id="cx">Cancel</button><button class="btn danger">Apply change to database</button></div></form>`);
 const f=$('#tf'),cur=()=>ledger.find(l=>l.seq==+f.s.value),del=()=>f.k.value=='del',
  upd=async()=>{const r=cur();$('#tv').hidden=del();$('#f0').textContent=r.hash;$('#f1').textContent=del()?'No record found':await sha(r.rec+'|amt='+f.v.value)},
  setv=()=>{const r=cur();f.v.value=(r.amt?+r.amt:r.rid*37)+50000;upd()};
 f.s.onchange=setv;f.oninput=upd;$('#cx').onclick=closeModal;setv();
 f.onsubmit=async e=>{e.preventDefault();const r=cur(),k=del()?'del':'edit',live=del()?'No record found':await sha(r.rec+'|amt='+f.v.value);r.tampered=true;r.tamperKind=k;r.live=live;if(k=='edit')r.amt=f.v.value;toast('Record changed directly in the database');render();
  $('.modal').innerHTML=`<h2>Change applied</h2><div class="alert warn" style="margin:12px 0"><span><b>${r.table}#${r.rid}</b> was ${k=='del'?'deleted':'edited'} in the database. Nothing has flagged it yet. CYFR finds it when records are verified.</span></div><div class="row"><button class="btn" id="cx">Close</button><button class="btn primary" id="rv">Run verification now</button></div>`;$('#cx').onclick=closeModal;$('#rv').onclick=openVerify}}
/* verification run */
async function openVerify(){const rows=OFFICES.map(o=>ledger.filter(l=>l.office==o)),paint=(i,bar)=>$('.modal').innerHTML=`<h2>Verifying records</h2><p class="muted">Re-hashing live records and comparing them with anchored fingerprints.</p><div class="pl">${OFFICES.map((o,k)=>{const bad=rows[k].filter(l=>l.tampered).length;return `<div class="${k<i?(bad?'x':'d'):k==i?'r':'p'}"><i>${k<i?(bad?'!':'✓'):k==i?'<span class="spin"></span>':''}</i><div><b>${o}</b><small>${k<i?rows[k].length+' records checked'+(bad?', '+bad+' mismatch':''):k==i?'Checking '+rows[k].length+' records…':'Waiting'}</small></div></div>`}).join('')}</div><div class="bar"><i style="width:${bar}%"></i></div>`;
 modal('');for(let i=0;i<OFFICES.length;i++){paint(i,i*25);await sleep(750)}paint(4,100);await sleep(400);
 state.lastVerify=new Date().toLocaleTimeString();const t=ledger.filter(l=>l.tampered);if(t.length)notify('bad','Verification flagged '+t.length+' mismatch'+(t.length>1?'es':'')+': '+t.map(l=>l.table+'#'+l.rid).join(', '));render();
 $('.modal').innerHTML=`<h2>Verification complete</h2><div class="alert ${t.length?'bad':'ok'}" style="margin:12px 0"><span><b>${t.length?t.length+' mismatch'+(t.length>1?'es':''):'All records match'}</b> out of ${ledger.length} records checked.</span></div>${t.length?`<div class="list">${t.map(l=>`<div class="row"><span><b>${l.table}#${l.rid}</b> · ${l.office}</span>${pill(l.tamperKind=='del'?'Deleted':'Value edited','bad')}</div>`).join('')}</div>`:''}<div class="row" style="margin-top:16px"><button class="btn" id="cx">Close</button><div style="display:flex;gap:8px">${t.length?'<button class="btn" id="pf">Print findings report</button>':''}<button class="btn primary" id="vd">View details</button></div></div>`;
 $('#cx').onclick=closeModal;$('#vd').onclick=()=>{closeModal();location.hash='#/verify'};const pf=$('#pf');pf&&(pf.onclick=()=>{closeModal();sheet('Tamper findings',repBody(1,30),'R-2611-30')})}
const va1=pages.verify.after;pages.verify.after=function(){va1();$('#tam').onclick=openTamper;$('#run').onclick=openVerify};
/* outage simulation */
function openOutage(){if(state.outage)return openRestore();
 modal(`<h2>Simulate an outage</h2><p class="muted">Offices in Naga face power and network interruptions often. See what CYFR does when the connection to the blockchain network drops.</p><form id="of" style="display:grid;gap:8px;margin-top:16px">${[['internet','Internet down','The office works normally. Fingerprints queue locally.'],['power','Power failure','Servers restart. The queue is recovered from disk.'],['both','Power and internet','The worst case. Nothing is lost.']].map((o,i)=>`<label class="opt"><input type="radio" name="t" value="${o[0]}" ${i?'':'checked'}><span><b>${o[1]}</b><small>${o[2]}</small></span></label>`).join('')}<div class="row" style="margin-top:8px"><button type="button" class="btn" id="cx">Cancel</button><button class="btn primary">Start outage</button></div></form>`);
 $('#cx').onclick=closeModal;$('#of').onsubmit=e=>{e.preventDefault();state.outageType=e.target.t.value;state.outage=true;state.outageSince=Date.now();closeModal();notify('warn',OUT[state.outageType][0]+' Changes are held in the offline queue.');toast('Outage started. Try adding a record');render()}}
function openRestore(){const n=queueN(),sec=Math.round((Date.now()-state.outageSince)/1000);
 modal(`<h2>Restore connection</h2><div class="alert warn" style="margin:12px 0"><span>${OUT[state.outageType][0]} Offline for ${Math.floor(sec/60)}m ${sec%60}s.</span></div><div class="grid g2e" style="margin-bottom:16px"><div class="card kpi"><small>Waiting in queue</small><b>${n}</b></div><div class="card kpi"><small>Records lost</small><b>0</b></div></div><div class="row"><button class="btn" id="cx">Stay offline</button><button class="btn primary" id="go">Restore and sync</button></div>`);
 $('#cx').onclick=closeModal;$('#go').onclick=async()=>{const S=[['Connection restored','Reached eGovChain'],['Checking sequence numbers','Looking for gaps in the local ledger'],['Anchoring '+n+' queued record'+(n==1?'':'s'),'Sending one batch']],paint=i=>$('.modal').innerHTML=`<h2>Syncing</h2><div class="pl">${S.map((s,k)=>`<div class="${k<i?'d':k==i?'r':'p'}"><i>${k<i?'✓':k==i?'<span class="spin"></span>':''}</i><div><b>${s[0]}</b><small>${s[1]}</small></div></div>`).join('')}</div>`;
  for(let i=0;i<3;i++){paint(i);await sleep(900)}state.outage=false;toast('Connection restored. Syncing the queue');if(!state.paused)_aq();render();
  $('.modal').innerHTML=`<h2>Back online</h2><div class="alert ok" style="margin:12px 0"><span><b>${state.paused?n+' records are still queued because anchoring is paused in Settings.':n+' records anchored. 0 lost. No gaps in the sequence.'}</b></span></div><div class="row"><span></span><button class="btn primary" id="cx">Done</button></div>`;$('#cx').onclick=closeModal}}
$('#outage').onclick=openOutage;
const _r=render;window.removeEventListener('hashchange',_r);
render=function(){_r();const o=$('#outage');o.textContent=state.outage?'Restore connection':'Simulate outage';o.classList.toggle('on',state.outage);
 if(state.outage){$('#banner').innerHTML=`<div class="alert warn"><span><b>${OUT[state.outageType][0]}</b> ${OUT[state.outageType][1]} (${queueN()} waiting)</span><button class="btn sm" id="rb">Restore connection</button></div>`;$('#rb').onclick=openRestore}};
window.addEventListener('hashchange',render);render();
